# Check if changed cells are "enclosed" (can't reach edge without crossing frame)
def is_enclosed(grid, r, c, frame_val, bg_val):
    """BFS to check if (r,c) can reach edge without crossing frame"""
    rows, cols = len(grid), len(grid[0])
    visited = set()
    queue = [(r, c)]

    while queue:
        curr_r, curr_c = queue.pop(0)
        if (curr_r, curr_c) in visited:
            continue
        visited.add((curr_r, curr_c))

        # Check if at edge
        if curr_r == 0 or curr_r == rows - 1 or curr_c == 0 or curr_c == cols - 1:
            return False  # Can reach edge, NOT enclosed

        # BFS neighbors
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = curr_r + dr, curr_c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == bg_val and (nr, nc) not in visited:
                    queue.append((nr, nc))

    return True  # Can't reach edge, IS enclosed

